const job = $input.first().json;
const regions = Array.isArray(job.regions) ? job.regions : [];
const max_pages = Number(job.max_pages ?? 5);

if (!regions.length) {
  return [{
    json: {
      ...job,
      current_region: '',
      max_pages,
      worker_error: 'No regions configured on search profile',
    },
  }];
}

return regions.map((current_region) => ({
  json: {
    ...job,
    current_region,
    max_pages,
  },
}));

const job = $json;
const params = new URLSearchParams();
params.set('limit', '24');
params.set('offset', '0');
params.set('sortBy', 'published_desc');
if (job.remonttityyppi) {
  params.set('freeText', job.remonttityyppi);
}
if (job.current_region) {
  params.append('locations[]', job.current_region);
}

return [{
  json: {
    ...job,
    oikotie_url: `https://asunnot.oikotie.fi/api/5.0/cards?${params.toString()}`,
  },
}];

const regionJob = $('For each region').item.json;
const probe = $input.first().json;

function extractTotalCount(payload) {
  if (!payload || typeof payload !== 'object') return 0;
  for (const key of ['total', 'totalCount', 'count']) {
    if (Number.isInteger(payload[key]) && payload[key] >= 0) return payload[key];
  }
  for (const nestedKey of ['data', 'meta']) {
    const nested = payload[nestedKey];
    if (!nested || typeof nested !== 'object') continue;
    for (const key of ['total', 'totalCount', 'count']) {
      if (Number.isInteger(nested[key]) && nested[key] >= 0) return nested[key];
    }
  }
  return 0;
}

function buildPageItems(total, maxPages = 5, pageSize = 24) {
  const cap = Math.max(1, maxPages);
  const limit = Math.max(1, pageSize);
  if (!total || total <= 0) return [{ page: 1, offset: 0, limit }];
  const totalPages = Math.min(cap, Math.max(1, Math.ceil(total / limit)));
  const items = [];
  for (let page = 1; page <= totalPages; page += 1) {
    items.push({ page, offset: (page - 1) * limit, limit });
  }
  return items;
}

const total = extractTotalCount(probe);
const pages = buildPageItems(total, regionJob.max_pages ?? 5, 24);

return pages.map((pageItem) => ({
  json: {
    ...regionJob,
    current_region: regionJob.current_region,
    page: pageItem.page,
    offset: pageItem.offset,
    limit: pageItem.limit,
  },
}));

const items = $('CALL – Lead Worker Universal').all();
const totals = {
  leads_found: 0,
  leads_sent: 0,
  duplicates: 0,
  failed_pages: 0,
  worker_error: '',
};

for (const item of items) {
  const row = item.json || {};
  if (row.worker_error) totals.worker_error = row.worker_error;
  totals.leads_found += Number(row.leads_found || 0);
  totals.leads_sent += Number(row.leads_sent || 0);
  totals.duplicates += Number(row.duplicates || 0);
  if (row.failed || row.page_failed) totals.failed_pages += 1;
}

return [{ json: totals }];
